styles:
.b-press-logos { margin: 2em 0; }
.b-press-logos__title { margin: 0 0 1em; font-size: 1.5em; text-align: center; }
.b-press-logos__list { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: 1.5em 2.5em; margin: 0; padding: 0; list-style: none; }
.b-press-logos__item { display: flex; }
.b-press-logos__link { display: flex; color: inherit; text-decoration: none; opacity: 0.75; transition: opacity 0.2s; }
.b-press-logos__link:hover, .b-press-logos__link:focus-visible { opacity: 1; }
.b-press-logos__logo { display: block; max-width: 10em; max-height: 3em; width: auto; height: auto; }
.b-press-logos__name { font-size: 1.1em; font-weight: 600; letter-spacing: 0.02em; }
